Here $n$ ($1 \le n \le \mathrm{MAXN}$) is the number of problems;
$happy\_score$ ($1 \le happy\_score \le \mathrm{MAXS}$) is the minimum score for Bob to be happy;
`time[]` is the array to store `time[i]` ($1 \le \mathtt{time[i]} \le 100$) which is the time to solve problem `i`;
`score[]` is the array to store `score[i]` ($1 \le \mathtt{score[i]} \le 100$) which is the score Bob gets for solving problem `i`.

#include <stdio.h>

#define MAXN 10
#define MAXS 1000

int need_time(const int time[], const int score[], int happy_score, int n);

int main() {
  int n, i, happy_score;
  int time[MAXN], score[MAXN];
  scanf("%d %d", &n, &happy_score);
  for (i = 0; i < n; ++i)
      scanf("%d", &time[i]);
  for (i = 0; i < n; ++i)
      scanf("%d", &score[i]);
  printf("%d\n", need_time(time, score, happy_score, n));
  return 0;
}

