int need_time(const int time[], const int score[], int happy_score, int n)
{
    const int INF = 1000000000;
    int dp[MAXS + 1];
    dp[0] = 0;
    for (int s = 1; s <= happy_score; ++s)
        dp[s] = INF;

    for (int i = 0; i < n; ++i) {
        for (int s = happy_score; s >= 1; --s) {
            int previous = s - score[i];
            if (previous < 0)
                previous = 0;
            if (dp[previous] != INF && dp[previous] + time[i] < dp[s])
                dp[s] = dp[previous] + time[i];
        }
    }
    return dp[happy_score] == INF ? -1 : dp[happy_score];
}

